package org.solarelevation.alarm;
import android.app.*;
import android.content.*;
import android.media.*;
import android.media.session.*;
import android.net.*;
import android.os.*;
import java.io.*;
import java.util.*;
public final class SolarAlarmPlaybackService extends Service {
public static final String SOURCE_ID="SolarAlarmPlaybackService_v20261022T031609Z";
private static final String CHANNEL="solar_alarm_media";
private MediaPlayer player;private SolarAlarmWvPlayback wavpack;private MediaSession session;private AudioFocusRequest focus;private AudioManager audio;private long active=-1,token=0;
public void onCreate(){super.onCreate();NotificationChannel channel=new NotificationChannel(CHANNEL,"Solar alarm playback",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(channel);session=new MediaSession(this,"SolarElevationAlarm");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){public void onStop(){finish("Stopped");}public void onPause(){finish("Stopped by media Pause");}public void onSeekTo(long position){finish("Stopped by external seek");}public void onSkipToNext(){finish("Stopped by external skip");}public void onSkipToPrevious(){finish("Stopped by external skip");}public void onPlay(){}});session.setActive(true);}
private Notification notification(String title){Intent stop=new Intent(this,SolarAlarmPlaybackService.class).setAction("STOP");PendingIntent stopAction=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(this,2,new Intent(this,SolarAlarmMainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Solar Elevation Alarm").setContentText(title).setOngoing(true).setContentIntent(open).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_pause,"Stop",stopAction).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0)).build();}
private void updateState(boolean playing){if(session!=null)session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_STOP|PlaybackState.ACTION_PAUSE).setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_STOPPED,PlaybackState.PLAYBACK_POSITION_UNKNOWN,playing?1f:0f).build());}
private void playbackState(long event,String state){getSharedPreferences("playback",0).edit().putLong("active_id",event).putString("state",state).putLong("updated",System.currentTimeMillis()).commit();}
private void started(long generation,long event,SolarAlarmStore.Event e){if(active!=event||token!=generation)return;playbackState(event,"playing");updateState(true);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(8317,notification(e.name+" · "+e.file));SolarAlarmStore s=new SolarAlarmStore(this);s.status(event,"Playing");s.close();}
public int onStartCommand(Intent intent,int flags,int id){String action=intent==null?"STOP":intent.getAction();if("STOP".equals(action)){finish("Stopped");return START_NOT_STICKY;}long event=intent.getLongExtra("event_id",-1);if(active>=0){if(event!=active){SolarAlarmStore s=new SolarAlarmStore(this);s.status(event,"Suppressed: playback already active");s.close();}return START_NOT_STICKY;}SolarAlarmStore db=new SolarAlarmStore(this);SolarAlarmStore.Event e=db.get(event);db.close();if(e==null||e.uri.isEmpty()){stopSelfResult(id);return START_NOT_STICKY;}active=event;playbackState(event,"preparing");long generation=++token;session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,e.name).putString(MediaMetadata.METADATA_KEY_ARTIST,e.file).build());startForeground(8317,notification(e.name+" · preparing"));updateState(false);try{SolarAlarmAudio.validate(this,e.uri,e.file);AudioAttributes attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();audio=(AudioManager)getSystemService(AUDIO_SERVICE);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attributes).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT)finish("Stopped: audio focus lost");}).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED)throw new IOException("Audio focus denied");if(e.file.toLowerCase(Locale.ROOT).endsWith(".wv")){wavpack=new SolarAlarmWvPlayback(this,e.uri,new SolarAlarmWvPlayback.Listener(){public void onStarted(){new Handler(Looper.getMainLooper()).post(()->started(generation,event,e));}public void onFinished(String outcome){new Handler(Looper.getMainLooper()).post(()->{if(token==generation&&active==event)finish(outcome);});}});wavpack.start();}else{player=new MediaPlayer();player.setAudioAttributes(attributes);player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);player.setDataSource(this,Uri.parse(e.uri));player.setOnPreparedListener(p->{if(active==event&&token==generation){p.start();started(generation,event,e);}});player.setOnCompletionListener(p->{if(token==generation)finish("Completed");});player.setOnErrorListener((p,what,extra)->{if(token==generation)finish("Playback error: "+what+"/"+extra);return true;});player.prepareAsync();}}catch(Exception ex){finish("Playback error: "+ex.getMessage());}catch(LinkageError ex){finish("Native playback error: "+ex.getMessage());}return START_NOT_STICKY;}
private synchronized void finish(String reason){long previous=active;active=-1;playbackState(-1,"idle");token++;SolarAlarmWvPlayback w=wavpack;wavpack=null;if(w!=null)w.stop();if(player!=null){try{player.stop();}catch(Exception ignored){}player.release();player=null;}updateState(false);if(audio!=null&&focus!=null){audio.abandonAudioFocusRequest(focus);focus=null;}if(previous>=0){SolarAlarmStore s=new SolarAlarmStore(this);s.status(previous,reason);s.close();}stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
public void onDestroy(){playbackState(-1,"idle");SolarAlarmWvPlayback w=wavpack;wavpack=null;if(w!=null)w.stop();if(player!=null){player.release();player=null;}if(audio!=null&&focus!=null){audio.abandonAudioFocusRequest(focus);focus=null;}if(active>=0){SolarAlarmStore store=new SolarAlarmStore(this);store.status(active,"Interrupted: service destroyed");store.close();active=-1;}if(session!=null){session.release();session=null;}super.onDestroy();}
public IBinder onBind(Intent i){return null;}
}
